#include "mrp.h"

void standard_costs(Model *model) { for (int i=model->item_count-1;i>=0;i--) { Item *item=&model->items[model->order[i]]; item->standard_material=item->material; item->standard_labor=item->labor; for (int j=0;j<item->child_count;j++) { Link *link=&model->links[item->children[j]]; Item *child=&model->items[link->child]; item->standard_material+=(link->quantity*(100+link->scrap)*child->standard_material+50)/100; item->standard_labor+=(link->quantity*(100+link->scrap)*child->standard_labor+50)/100; } item->standard_total=item->standard_material+item->standard_labor; } }
void abc_classes(Model *model) { int order[100]; int64_t total=0,before=0; for (int i=0;i<model->item_count;i++) { total+=model->items[i].value; int j=i; while (j>0) { Item *a=&model->items[order[j-1]],*b=&model->items[i]; if (a->value>b->value || (a->value==b->value && strcmp(a->id,b->id)<=0)) break; order[j]=order[j-1]; j--; } order[j]=i; } for (int i=0;i<model->item_count;i++) { Item *item=&model->items[order[i]]; item->abc=!item->value ? 'C' : 100*before<80*total ? 'A' : 100*before<95*total ? 'B' : 'C'; before+=item->value; } }
